"""Structured, independently tracked practice paths for Code Academy 4.0."""
from dataclasses import dataclass

@dataclass(frozen=True)
class Exercise:
    slug: str
    section: str
    title: str
    explanation: str
    example: str
    expected: str
    task: str
    hint: str

