SQL = [
('Основы','SELECT','SELECT выбирает столбцы из таблицы.','SELECT name FROM students ORDER BY id;','Алия | Бек | Дана','Выведи имена студентов.','SELECT name FROM students.'),
('Основы','Все столбцы','Звёздочка * означает все столбцы таблицы.','SELECT * FROM students LIMIT 1;','1 | Алия | Медицина','Выведи одну запись целиком.','SELECT * и LIMIT 1.'),
('Основы','WHERE','WHERE фильтрует записи по условию.','SELECT name FROM students WHERE id = 2;','Бек','Найди студента с id=2.','WHERE id = 2.'),
('Основы','ORDER BY','ORDER BY сортирует строки.','SELECT name FROM students ORDER BY name;','Алия | Бек | Дана','Отсортируй имена.','ORDER BY name.'),
('Основы','LIMIT','LIMIT ограничивает количество возвращаемых строк.','SELECT name FROM students ORDER BY id LIMIT 2;','Алия | Бек','Покажи две первые записи.','LIMIT 2.'),
('Фильтры','Неравенство','Оператор <> означает не равно.','SELECT name FROM students WHERE id <> 1 ORDER BY id;','Бек | Дана','Исключи запись с id=1.','<>.'),
('Фильтры','Числовой диапазон','Сравнение > выбирает значения больше порога.','SELECT name FROM students WHERE id > 1 ORDER BY id;','Бек | Дана','Выбери id больше 1.','WHERE id > 1.'),
('Фильтры','AND','AND объединяет два условия.','SELECT name FROM students WHERE id > 1 AND id < 3;','Бек','Ограничь диапазон.','AND.'),
('Фильтры','OR','OR выбирает строки, удовлетворяющие любому условию.','SELECT name FROM students WHERE id = 1 OR id = 3 ORDER BY id;','Алия | Дана','Выбери id 1 и 3.','OR.'),
('Фильтры','LIKE','LIKE ищет по шаблону; % обозначает произвольную последовательность.','SELECT name FROM students WHERE name LIKE "А%";','Алия','Найди имена на А.','LIKE "А%".'),
('Агрегация','COUNT','COUNT(*) считает строки.','SELECT COUNT(*) FROM students;','3','Посчитай строки таблицы.','COUNT(*).'),
('Агрегация','GROUP BY','GROUP BY объединяет строки по значению поля.','SELECT faculty, COUNT(*) FROM students GROUP BY faculty ORDER BY faculty;','Медицина | 2; Стоматология | 1','Посчитай студентов по факультету.','GROUP BY faculty.'),
('Агрегация','DISTINCT','DISTINCT убирает повторяющиеся значения результата.','SELECT DISTINCT faculty FROM students ORDER BY faculty;','Медицина | Стоматология','Получи уникальные факультеты.','SELECT DISTINCT.'),
('Агрегация','COUNT DISTINCT','COUNT(DISTINCT ...) считает уникальные непустые значения.','SELECT COUNT(DISTINCT faculty) FROM students;','2','Посчитай уникальные факультеты.','COUNT(DISTINCT faculty).'),
('Агрегация','HAVING','HAVING фильтрует группы после GROUP BY.','SELECT faculty, COUNT(*) FROM students GROUP BY faculty HAVING COUNT(*) > 1;','Медицина | 2','Найди группы более одного студента.','HAVING COUNT(*) > 1.'),
('Связи','JOIN','JOIN соединяет строки двух таблиц по ключам.','SELECT s.name, f.title FROM students s JOIN faculties f ON s.faculty = f.code ORDER BY s.id;','Алия | Школа медицины; Бек | Школа стоматологии; Дана | Школа медицины','Соедини студентов с факультетами.','JOIN ... ON.'),
('Связи','LEFT JOIN','LEFT JOIN сохраняет строки левой таблицы даже без совпадения.','SELECT s.name, f.title FROM students s LEFT JOIN faculties f ON s.faculty = f.code ORDER BY s.id;','Алия | Школа медицины; Бек | Школа стоматологии; Дана | Школа медицины','Сохрани всех студентов.','LEFT JOIN.'),
('Связи','Псевдонимы','AS даёт столбцу понятное имя в результате.','SELECT COUNT(*) AS total FROM students;','3','Назови итог total.','AS total.'),
('Продвинутые','Подзапрос','Вложенный SELECT может использоваться внутри WHERE.','SELECT name FROM students WHERE id IN (SELECT id FROM students WHERE id > 1) ORDER BY id;','Бек | Дана','Отфильтруй через подзапрос.','IN (SELECT ...).'),
('Продвинутые','CTE','WITH создаёт именованный временный результат запроса.','WITH s AS (SELECT * FROM students WHERE id > 1) SELECT COUNT(*) FROM s;','2','Сосчитай строки с помощью CTE.','WITH s AS (...).'),
('Продвинутые','CASE','CASE задаёт условные значения в результате.','SELECT CASE WHEN id = 1 THEN "Первый" ELSE "Другой" END FROM students WHERE id = 1;','Первый','Используй условное выражение.','CASE WHEN.'),
('Продвинутые','Оконные функции','ROW_NUMBER() нумерует строки без группировки.','SELECT name, ROW_NUMBER() OVER (ORDER BY id) FROM students;','Алия | 1; Бек | 2; Дана | 3','Пронумеруй записи.','ROW_NUMBER() OVER.'),
]

def lessons(kind):
    source = PYTHON if kind == 'python' else SQL
    return [Exercise(f'{kind}-{i:03d}', *row) for i,row in enumerate(source,1)]
